mapper.select:
SELECT COUNT(*)
FROM member
WHERE register_time >= #{beginTime} AND register_time < #{endTime}

SELECT soi.goods_id AS goodsId, g.goods_code AS goodsCode, soi.goods_name AS goodsName, g.category_id AS categoryId, c.name AS categoryName, g.brand_id AS brandId, b.name AS brandName, COUNT(DISTINCT soi.order_id) AS orderCount, COALESCE(SUM(soi.quantity), 0) AS qty, COALESCE(SUM(soi.amount), 0) AS salesAmount, COALESCE(SUM(soi.discount_amount), 0) AS discountAmount, COALESCE(SUM(soi.paid_amount), 0) AS netSalesAmount, NULL AS refundAmount, COALESCE(SUM(soi.cost_amount), 0) AS costAmount, NULL AS returnCostAmount, COALESCE(SUM(soi.profit_amount), 0) AS profitAmount, NULL AS profitRate, NULL AS shareRate, NULL AS stockQty, NULL AS costPrice, NULL AS occupiedAmount, NULL AS retailPrice FROM sales_order_item soi JOIN sales_order so ON so.id = soi.order_id LEFT JOIN goods g ON g.id = soi.goods_id LEFT JOIN category c ON c.id = g.category_id LEFT JOIN brand b ON b.id = g.brand_id WHERE so.business_date BETWEEN #{begin} AND #{end} AND soi.goods_id IS NOT NULL
AND g.category_id = #{categoryId}
GROUP BY soi.goods_id, g.goods_code, soi.goods_name, g.category_id, c.name, g.brand_id, b.name ORDER BY ${orderBy} DESC, soi.goods_id

SELECT g.id AS goodsId, g.goods_code AS goodsCode, g.name AS goodsName, g.category_id AS categoryId, c.name AS categoryName, NULL AS brandId, NULL AS brandName, 0 AS orderCount, COALESCE(s.qty, 0) AS qty, NULL AS salesAmount, NULL AS discountAmount, NULL AS netSalesAmount, NULL AS refundAmount, NULL AS costAmount, NULL AS returnCostAmount, NULL AS profitAmount, NULL AS profitRate, NULL AS shareRate, i.quantity AS stockQty, i.cost_price AS costPrice, (i.quantity * i.cost_price) AS occupiedAmount, g.retail_price AS retailPrice FROM goods g JOIN inventory i ON i.goods_id = g.id LEFT JOIN category c ON c.id = g.category_id LEFT JOIN (SELECT soi.goods_id, SUM(soi.quantity) AS qty FROM sales_order_item soi JOIN sales_order so ON so.id = soi.order_id WHERE so.business_date BETWEEN #{begin} AND #{end} GROUP BY soi.goods_id) s ON s.goods_id = g.id WHERE g.status = 1 AND COALESCE(s.qty, 0) < #{threshold}
AND g.category_id = #{categoryId}
ORDER BY occupiedAmount DESC, g.id
